from .enums import ConfirmationOutcome,ConfirmationState
REASON_CODES={
"FP_CRC_CANDIDATE_ADMITTED":"Active FP-I06 candidate admitted once.","FP_CRC_HUNTER_ONLY_AT_CLOSE":"Initial one-sided asymmetry persists at close.","FP_CRC_BOTH_TOUCHED_AT_CLOSE":"Both symbols touched by close.","FP_CRC_ROLE_CHANGED_AT_CLOSE":"Only protected side remains at close.","FP_CRC_NONE_AT_CLOSE":"No one-sided state remains.","FP_CRC_DATA_INCOMPLETE_AT_CLOSE":"Required close evidence incomplete.","FP_CRC_SIGNAL_CONFIRMED":"First eligible closed host bar confirmed signal.","FP_CRC_PROTECTED_TOUCH_BEFORE_CONFIRMATION":"Protected symbol touched before confirmation.","FP_CRC_ASYMMETRY_ABSENT_AT_CLOSE":"Asymmetry absent at close.","FP_CRC_UNAVAILABLE_AT_CLOSE":"Coverage or causal availability incomplete at close.","FP_CRC_CONFIRMATION_DEADLINE_MISSED":"Host close was at/after strict session deadline.","FP_CRC_MISSED_CLOSE_REPLAY_REQUIRED":"Live processor missed target close; deterministic replay required.","FP_CRC_PENDING_INVALIDATED_BY_REVISION":"Pending candidate source range revised.","FP_CRC_CONFIRMED_EVIDENCE_PRESERVED":"Confirmed signal remains immutable under later revision.","FP_CRC_TERMINAL_RESULT_UNAFFECTED":"Terminal audit result is not rewritten.","FP_CRC_REVISION_OUTSIDE_CANDIDATE_RANGE":"Revision does not overlap candidate confirmation range.","FP_CRC_ENGINE_READY":"No pending candidates and no blocking outcomes.","FP_CRC_ENGINE_READY_PENDING":"Pending confirmations exist with healthy inputs.","FP_CRC_ENGINE_BLOCKED_REPLAY_OR_DATA":"Replay or unavailable-data outcome blocks trust."}
OUTCOME_TO_STATE={ConfirmationOutcome.CONFIRMED:ConfirmationState.CONFIRMED,ConfirmationOutcome.INVALIDATED_DOUBLE_HUNT:ConfirmationState.CANCELLED_SECOND_TOUCH,ConfirmationOutcome.INVALIDATED_ROLE_CHANGED:ConfirmationState.CANCELLED_ROLE_CHANGED,ConfirmationOutcome.NO_SIGNAL_AT_CLOSE:ConfirmationState.NO_SIGNAL_AT_CLOSE,ConfirmationOutcome.UNAVAILABLE_AT_CLOSE:ConfirmationState.INVALID_DATA,ConfirmationOutcome.CONFIRMATION_DEADLINE_MISSED:ConfirmationState.EXPIRED_DEADLINE,ConfirmationOutcome.MISSED_CLOSE_REPLAY_REQUIRED:ConfirmationState.MISSED_CLOSE_REPLAY_REQUIRED}
def validate_registry():
    assert len(REASON_CODES)>=19
    assert set(OUTCOME_TO_STATE)==set(ConfirmationOutcome)
    return True
